-- Rich demo calendar + timetable seed (idempotent on fixed IDs).

-- Drop ad-hoc years that collide with demo names so fixed UUIDs can be used
DELETE FROM calendar_events
WHERE academic_year_id IN (
  SELECT id FROM academic_years
  WHERE (institution_id, name) IN (
    ('a0000000-0000-4000-8000-000000000001', '2025'),
    ('a0000000-0000-4000-8000-000000000001', '2026'),
    ('a0000000-0000-4000-8000-000000000002', '2025'),
    ('a0000000-0000-4000-8000-000000000002', '2026')
  )
  AND id NOT IN (
    'aa000000-0000-4000-8000-000000000001',
    'aa000000-0000-4000-8000-000000000002',
    'aa000000-0000-4000-8000-000000000003',
    'aa000000-0000-4000-8000-000000000004'
  )
);

DELETE FROM academic_years
WHERE (institution_id, name) IN (
  ('a0000000-0000-4000-8000-000000000001', '2025'),
  ('a0000000-0000-4000-8000-000000000001', '2026'),
  ('a0000000-0000-4000-8000-000000000002', '2025'),
  ('a0000000-0000-4000-8000-000000000002', '2026')
)
AND id NOT IN (
  'aa000000-0000-4000-8000-000000000001',
  'aa000000-0000-4000-8000-000000000002',
  'aa000000-0000-4000-8000-000000000003',
  'aa000000-0000-4000-8000-000000000004'
);

